        realtype AUX_VAR_H_IL10_Breg = (_species_var[SP_V_T_IL10] / AUX_VAR_V_T) / (PARAM(P_IL10_50_Breg) + (_species_var[SP_V_T_IL10] / AUX_VAR_V_T));
